import sqlite3,sys,json,hashlib
c=sqlite3.connect(f"file:{sys.argv[1]}?mode=ro",uri=True)
h=lambda s:"sha256:"+hashlib.sha256(s.encode()).hexdigest()
out={"runs":[],"roots":[],"leases":[],"attempts":[],"observationClaims":[]}
for rid,rev,st,rj,ca,ua in c.execute("select * from workflow_runs"):
    r=json.loads(rj); be=r["plan"].get("bootstrapExecution",{}).get("context") or {}
    stages=[]
    for s in r.get("stageResults",[]):
        ec=s.get("executionContext") or {}
        stages.append({"stageId":s["stageId"],"state":s["state"],"outputFile":s.get("outputFile"),"artifacts":[{"artifactId":a["artifactId"],"digest":a["digest"]} for a in s["output"]["artifacts"]],
          "executionContext":{k:ec.get(k) for k in("model","modelClass","reasoningEffort","source","observationId","actorId","observedAt")}})
    out["runs"].append({"runId":rid,"revision":rev,"state":st,"receiptDigest":h(rj),"selected":r["plan"].get("selectedSkills"),
      "stages":[{"stageId":s["stageId"],"providerId":s.get("providerId"),"phaseOrder":s.get("phaseOrder")} for s in r["plan"]["stages"]],
      "bootstrapContext":{k:be.get(k) for k in("model","modelClass","reasoningEffort","source","observationId","actorId")},"stageResults":stages,"createdAt":ca,"updatedAt":ua})
for row in c.execute("select root_id,revision,state,workspace_id from convergence_roots"): out["roots"].append(dict(zip(["rootId","revision","state","workspaceId"],row)))
for row in c.execute("select lease_id,root_id,state,lease_json from convergence_leases"):
    lj=json.loads(row[3]); out["leases"].append({"leaseId":row[0],"rootId":row[1],"state":row[2],"actorId":lj.get("actorId")})
for row in c.execute("select root_id,lease_id,run_id,state from convergence_attempts"): out["attempts"].append(dict(zip(["rootId","leaseId","runId","state"],row)))
for row in c.execute("select * from execution_observation_claims"): out["observationClaims"].append(dict(zip(["observationId","expiresAt","consumedAt"],row)))
print(json.dumps(out,indent=1))
PY

